package com.example.examplemod.economy;
import com.example.examplemod.railway.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import java.util.*;
/** Exercises production escrow, limits, multi-buyer settlement and crash reconciliation. */
public final class FreightCarrierCheck{
 private static int checks;private static final ResourceLocation WORLD=ResourceLocation.parse("minecraft:overworld"),ITEM=ResourceLocation.parse("minecraft:iron_ingot");
 private static void require(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 @SuppressWarnings("unchecked") private static <T> Map<UUID,T> map(EconomyManager m,String name)throws Exception{var f=EconomyManager.class.getDeclaredField(name);f.setAccessible(true);return (Map<UUID,T>)f.get(m);}
 private static final class Fixture{
  final EconomyManager manager=new EconomyManager();final UUID seller=UUID.randomUUID(),first=UUID.randomUUID(),second=UUID.randomUUID(),operator=UUID.randomUUID();final UUID a,b;
  Fixture()throws Exception{a=order(first);b=order(second);FreightCarrierCheck.<Long>map(manager,"treasuries").put(first,1000L);FreightCarrierCheck.<Long>map(manager,"treasuries").put(second,1000L);}
  UUID order(UUID buyer)throws Exception{var src=new FreightPoint(UUID.randomUUID(),seller,WORLD,BlockPos.ZERO,new BlockPos(2,0,0),"Source",FreightPoint.Mode.SEND);var dst=new FreightPoint(UUID.randomUUID(),buyer,WORLD,new BlockPos(40,0,0),new BlockPos(42,0,0),"Destination",FreightPoint.Mode.RECEIVE);src.status=dst.status="online";src.station=UUID.randomUUID();dst.station=UUID.randomUUID();manager.freight().points.put(src.id,src);manager.freight().points.put(dst.id,dst);
   var c=new IndustrialContract(UUID.randomUUID(),EconomyTypes.ContractKind.ORDINARY,EconomyTypes.ContractMode.EXCLUSIVE,buyer,buyer,"Order","",ITEM,128,100,dst.id,null,1,12000);c.accept(seller,seller,1);FreightCarrierCheck.<IndustrialContract>map(manager,"contracts").put(c.id(),c);manager.freight().bind(c.id(),src.id,dst);var a=manager.freight().assignments.get(c.id());a.buyerTransport=true;a.running=true;require(manager.freight().carriers.budget(c.id(),buyer,200).equals("ok"),"buyer authorizes real allowance");return c.id();}
 }
 public static void main(String[] args)throws Exception{
  bootstrap();UUID trip=UUID.randomUUID();var budget=new FreightTransportBudget();require(budget.limit(100)&&budget.reserve(trip,70),"reserve permitted allowance");require(budget.reserve(trip,70)&&budget.reserved()==70,"repeated reserve idempotent");require(!budget.reserve(UUID.randomUUID(),31)&&!budget.limit(69),"limit cannot be bypassed or undercut");
  var restored=FreightTransportBudget.load(budget.save());require(restored.settle(trip,41)&&restored.spent()==41&&restored.reserved()==0&&restored.remaining()==59,"partial trip refunds unused allowance");require(!restored.settle(trip,41)&&!restored.reserve(trip,70),"closed trip cannot spend again");require(!FreightTransportBudget.load(restored.save()).reserve(trip,1),"replay blocked across reload");
  for(int total=0;total<200;total++){var split=FreightCostSharing.split(total,List.of(64L,128L,1L));require(split.stream().mapToLong(Long::longValue).sum()==total,"integer shares conserve CR");}require(FreightCostSharing.split(Long.MAX_VALUE,List.of(Long.MAX_VALUE,Long.MAX_VALUE)).stream().mapToLong(Long::longValue).sum()==Long.MAX_VALUE,"large weights do not overflow");
  var f=new Fixture();var road=f.manager.freight().roadCharges;UUID charged=UUID.randomUUID();require(road.reserveShares(Map.of(f.a,64L,f.b,128L),charged,120),"shared leg reserves buyer escrows");require(f.manager.treasury(f.first)==960&&f.manager.treasury(f.second)==920,"tariff shares use cargo quantities");require(!road.reserveShares(Map.of(f.a,64L),charged,120),"repeated departure cannot reserve twice");
  var loaded=reload(f.manager.save(new CompoundTag(),null));require(loaded.freight().roadCharges.managed(charged)&&loaded.freight().carriers.budget(f.a).reserved()==40,"charge allocations and limits survive restart together");
  var actualRailway=new RailwayManager();var ledger=new RailwayTripLedger(charged,UUID.randomUUID(),UUID.randomUUID(),RailwayOwnershipTypes.OwnerType.CITY,f.first,UUID.randomUUID(),UUID.randomUUID(),100,120,1,List.of()).commercial(true);actualRailway.addTrip(ledger);
  var readRailway=RailwayManager.class.getDeclaredMethod("load",CompoundTag.class,net.minecraft.core.HolderLookup.Provider.class);readRailway.setAccessible(true);var railwayRestored=(RailwayManager)readRailway.invoke(null,actualRailway.save(new CompoundTag(),null),null);require(railwayRestored.tripLedgers().getFirst().commercial(),"commercial marker survives railway save independently");loaded.freight().roadCharges.reconcile(railwayRestored);require(loaded.treasury(f.first)==960,"active persisted ledger retains its buyer reserve");
  var payouts=List.of(new EconomyManager.TransportPayout(true,f.operator,61));require(loaded.freight().roadCharges.settle(charged,payouts),"actual charge settles after restart");require(loaded.treasury(f.first)+loaded.treasury(f.second)+loaded.treasury(f.operator)==2000,"buyer refunds plus road revenue conserve money");require(loaded.treasury(f.operator)==61&&loaded.freight().carriers.budget(f.a).reserved()==0,"no carrier fee or trapped reservation");
  long balance=loaded.treasury(f.first);require(loaded.freight().roadCharges.settle(charged,payouts)&&loaded.treasury(f.operator)==61&&loaded.treasury(f.first)==balance,"settlement retry cannot repeat payout");var twice=reload(loaded.save(new CompoundTag(),null));require(twice.freight().roadCharges.settle(charged,payouts)&&twice.treasury(f.operator)==61,"settlement replay blocked after another reload");
  var insufficient=new Fixture();insufficient.manager.freight().carriers.budget(insufficient.a).limit(1);long untouched=insufficient.manager.treasury(insufficient.second);require(!insufficient.manager.freight().roadCharges.reserveShares(Map.of(insufficient.a,64L,insufficient.b,128L),UUID.randomUUID(),120)&&insufficient.manager.treasury(insufficient.first)==1000&&insufficient.manager.treasury(insufficient.second)==untouched,"one exhausted limit prevents all debits");
  var orphan=new Fixture();UUID interrupted=UUID.randomUUID();require(orphan.manager.freight().roadCharges.reserveShares(Map.of(orphan.a,1L),interrupted,100),"pre-ledger reserve exists");var afterCrash=reload(orphan.manager.save(new CompoundTag(),null));afterCrash.freight().roadCharges.reconcile(new RailwayManager());require(afterCrash.treasury(orphan.first)==1000&&afterCrash.freight().carriers.budget(orphan.a).reserved()==0,"orphan reservation refunded if railway save was interrupted");afterCrash.freight().roadCharges.reconcile(new RailwayManager());require(afterCrash.treasury(orphan.first)==1000,"orphan refund is idempotent");
  var disabled=f.manager.freight().point(f.manager.freight().assignments.get(f.a).source);disabled.enabled=false;require(f.manager.freight().control(f.first,f.a,null,false,null)&&!f.manager.freight().assignments.get(f.a).running,"pause does not depend on physical source availability");disabled.enabled=true;f.manager.freight().assignments.get(f.a).running=true;
  require(!f.manager.freight().carriers.budget(f.a,f.seller,500).equals("ok"),"seller cannot change buyer allowance");var railway=new RailwayManager();var train=railway.registerTrain(UUID.randomUUID(),f.seller,"Trade train");railway.attachTrainToCity(train.fleetTrainId(),f.seller,f.seller);require(!f.manager.freight().carriers.publish(railway,f.first,train.fleetTrainId(),true).equals("ok"),"foreign city cannot publish a train");require(f.manager.freight().carriers.publish(railway,f.seller,train.fleetTrainId(),true).equals("ok"),"owner publication explicit");f.manager.freight().assignments.get(f.a).train=train.fleetTrainId();require(f.manager.freight().carriers.booked(train.fleetTrainId(),f.b)&&!f.manager.freight().carriers.publish(railway,f.seller,train.fleetTrainId(),false).equals("ok"),"active delivery holds lease");
  var closedRailway=new Fixture();UUID closing=UUID.randomUUID();closedRailway.manager.freight().roadCharges.reserveShares(Map.of(closedRailway.a,1L),closing,100);var closedLedger=new RailwayTripLedger(closing,UUID.randomUUID(),UUID.randomUUID(),RailwayOwnershipTypes.OwnerType.CITY,closedRailway.first,UUID.randomUUID(),UUID.randomUUID(),100,100,1,List.of(new RailwayTariffLeg(UUID.randomUUID(),RailwayOwnershipTypes.OwnerType.CITY,closedRailway.operator,1000,0,100,100))).commercial(true);closedLedger.progress(50);closedLedger.close(RailwayTripLedger.Status.INTERRUPTED,2);var closedManager=new RailwayManager();closedManager.addTrip(closedLedger);var savedBeforeSettlement=reload(closedRailway.manager.save(new CompoundTag(),null));savedBeforeSettlement.freight().roadCharges.reconcile(closedManager);require(savedBeforeSettlement.treasury(closedRailway.first)==950&&savedBeforeSettlement.treasury(closedRailway.operator)==50&&savedBeforeSettlement.freight().carriers.budget(closedRailway.a).reserved()==0,"closed railway ledger repairs older open economy escrow");savedBeforeSettlement.freight().roadCharges.reconcile(closedManager);require(savedBeforeSettlement.treasury(closedRailway.operator)==50,"cross-save reconciliation cannot pay twice");
  var old=f.manager.save(new CompoundTag(),null);old.putInt("FormatVersion",11);var fr=old.getCompound("FreightLogistics");fr.remove("Carriers");fr.remove("RoadCharges");for(Tag raw:fr.getList("Assignments",10))((CompoundTag)raw).remove("BuyerTransport");var migrated=reload(old);require(!migrated.freight().assignments.get(f.a).buyerTransport&&migrated.contract(f.a)!=null,"legacy dispatch remains legacy; no guessed payer or money migration");
  System.out.println("PASS: "+checks+" freight allowance, shared escrow, replay, ownership and restart assertions");
 }
 private static EconomyManager reload(CompoundTag t)throws Exception{var m=EconomyManager.class.getDeclaredMethod("load",CompoundTag.class,net.minecraft.core.HolderLookup.Provider.class);m.setAccessible(true);return (EconomyManager)m.invoke(null,t,null);}
 private static void bootstrap()throws Exception{var f=com.example.examplemod.Config.class.getDeclaredField("SPEC");f.setAccessible(true);var spec=(net.neoforged.neoforge.common.ModConfigSpec)f.get(null);var config=com.electronwill.nightconfig.core.CommentedConfig.inMemory();spec.correct(config);config.set("items",List.of());var type=Class.forName("net.neoforged.fml.config.LoadedConfig");var ctor=type.getDeclaredConstructors()[0];ctor.setAccessible(true);spec.acceptConfig((net.neoforged.fml.config.IConfigSpec.ILoadedConfig)ctor.newInstance(config,null,null));}
}
